11.4 Split: Entrenamiento vs Testeo


Código
splits &lt;- time_series_split(data_prepared_tbl,
                             assess     = "36 months", # 3 anios
                             cumulative = TRUE) 

splits


&lt;Analysis/Assess/Total&gt;
&lt;159/36/195&gt;


Código
splits |&gt;
  tk_time_series_cv_plan() |&gt;
  plot_time_series_cv_plan(Fecha, Prod_trans)

11.5 Modelos
Ahora ajustamos algunas variantes de la familia ARIMA.

La versión automatizada



Código
mod_fit_autoarima &lt;- arima_reg() |&gt; 
  set_engine("auto_arima") |&gt;
  fit(Prod_trans ~ Fecha, data = training(splits))


Vemos su performance en el grupo de testeo:


Código
modeltime_table(mod_fit_autoarima) |&gt;
  modeltime_calibrate(testing(splits)) |&gt;
  modeltime_forecast(
    new_data    = testing(splits),
    actual_data = data_prepared_tbl
  ) |&gt;
  plot_modeltime_forecast(.conf_interval_show = FALSE)






😐
Con la información que detectamos en el EDA, podemos proponer algunas alternativas:


Código
# 6.2 SARIMA especificado (estacionalidad de 12 meses)
mod_fit_sarima &lt;- arima_reg(
    non_seasonal_ar           = 1,   # p
    non_seasonal_differences  = 1,   # d
    seasonal_period           = 12,  # m
    seasonal_ar               = 1,   # P
    seasonal_differences      = 1,   # D
    seasonal_ma               = 0    # Q
  ) |&gt;
  set_engine("arima") |&gt;
  fit(Prod_trans ~ Fecha, training(splits))

modeltime_table(
  mod_fit_autoarima,
  mod_fit_sarima
) |&gt;
  modeltime_calibrate(testing(splits)) %&gt;%
  modeltime_forecast(
    new_data    = testing(splits),
    actual_data = data_prepared_tbl
  ) |&gt;
  plot_modeltime_forecast(.conf_interval_show = FALSE)






😲


Código
mod_fit_arima &lt;- arima_reg(
    non_seasonal_ar            = 1,   # p 
    non_seasonal_differences   = 1,   # d  
    seasonal_period            = 12,  # m
    seasonal_ar                = 1,   # P  
    seasonal_differences       = 0,   # D 
    seasonal_ma                = 0    # Q
  ) |&gt;
  set_engine("arima", include.drift = FALSE)|&gt;
  fit(Prod_trans ~ Fecha, training(splits))

modeltime_table(
  mod_fit_autoarima,
  mod_fit_sarima,
  mod_fit_arima
) |&gt;
  modeltime_calibrate(testing(splits)) %&gt;%
  modeltime_forecast(
    new_data    = testing(splits),
    actual_data = data_prepared_tbl
  ) |&gt;
  plot_modeltime_forecast(.conf_interval_show = FALSE)






😐


Código
mod_fit_sarima2 &lt;- arima_reg(
    non_seasonal_ar            = 2,   # p 
    non_seasonal_differences   = 1,   # d  
    seasonal_period            = 12,  # m
    seasonal_ar                = 2,   # P  
    seasonal_differences       = 1,   # D 
    seasonal_ma                = 0   # Q
  ) |&gt;
  set_engine("arima") |&gt;
  fit(Prod_trans ~ Fecha, training(splits))

modeltime_table(
  mod_fit_autoarima,
  mod_fit_sarima,
  mod_fit_arima,
  mod_fit_sarima2
) |&gt;
  modeltime_calibrate(testing(splits)) |&gt;
  modeltime_forecast(
    new_data    = testing(splits),
    actual_data = data_prepared_tbl
  ) |&gt;
  plot_modeltime_forecast(.conf_interval_show = FALSE)






😯 Peligro de sobre ajuste (overfitting)

11.6 Métricas de desempeño en el conjunto de testeo


Código
modeltime_table(
  mod_fit_autoarima,
  mod_fit_sarima,
  mod_fit_arima,
  mod_fit_sarima2
) |&gt;
  modeltime_calibrate(testing(splits)) |&gt;
  modeltime_accuracy(
    metric_set = metric_set(mae, rmse, mape)) |&gt;
    table_modeltime_accuracy()
